<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'new');if(!in_array($status,['new','in_progress','completed','spam'],true))throw new RuntimeException('Status yanlışdır.');$q=$pdo->prepare('UPDATE inquiries SET status=? WHERE id=?');$q->execute([$status,$id]);$success='Müraciətin statusu yeniləndi.';}catch(Throwable $x){$error='Məlumat yenilənmədi.';}}
$rows=$pdo->query('SELECT i.*,s.title AS service_title FROM inquiries i LEFT JOIN services s ON s.id=i.service_id ORDER BY i.created_at DESC LIMIT 200')->fetchAll();admin_header('Müraciətlər','inquiries');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<section class="panel"><div class="panel-head"><div><small>ƏLAQƏ FORMASI</small><h2>Daxil olan müraciətlər</h2></div><span class="count"><?=count($rows)?> / 200</span></div><div class="table-wrap"><table><thead><tr><th>Tarix</th><th>Müştəri</th><th>Əlaqə</th><th>Müraciət</th><th>Status</th><th>Yenilə</th></tr></thead><tbody><?php foreach($rows as $i):?><tr><td><?=e($i['created_at'])?></td><td><b><?=e($i['full_name'])?></b><small class="subline"><?=e($i['service_title']??'Ümumi müraciət')?></small></td><td><?=e($i['email'])?><small class="subline"><?=e($i['phone']??'')?></small></td><td><?=e($i['subject']??'')?><small class="subline"><?=e($i['message'])?></small></td><td><?=e(['new'=>'Yeni','in_progress'=>'Baxılır','completed'=>'Tamamlandı','spam'=>'Spam'][$i['status']]??$i['status'])?></td><td><form method="post" class="inline-status"><?=csrf_field()?><input type="hidden" name="id" value="<?=$i['id']?>"><select name="status"><option value="new" <?=$i['status']==='new'?'selected':''?>>Yeni</option><option value="in_progress" <?=$i['status']==='in_progress'?'selected':''?>>Baxılır</option><option value="completed" <?=$i['status']==='completed'?'selected':''?>>Tamamlandı</option><option value="spam" <?=$i['status']==='spam'?'selected':''?>>Spam</option></select><button class="btn-admin">Yadda saxla</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Müraciət yoxdur.</td></tr><?php endif;?></tbody></table></div></section><?php admin_footer();?>